class WriteBackCache:
    def __init__(self, store, max_dirty=10000):
        self.cache = {}   # k -> (value, version)
        self.dirty = {}   # k -> (value, version)
        self.store = store
        self.max_dirty = max_dirty
        self.seq = 0

    def put(self, k, v):
        # Backpressure: bound the loss window instead of growing it.
        if len(self.dirty) >= self.max_dirty:
            self.flush_oldest()  # or raise / degrade to write-through
        self.seq += 1
        self.cache[k] = (v, self.seq)
        self.dirty[k] = (v, self.seq)  # ACK happens here; store not yet updated
        return True  # means durable-in-cache only

    def get(self, k):
        if k in self.cache:
            return self.cache[k][0]  # must serve dirty values from cache
        v = self.store.load(k)  # miss: install as clean
        self.cache[k] = (v, 0)
        return v

    def flush(self, k):
        if k not in self.dirty:
            return
        v, ver = self.dirty[k]
        # Store must reject stale versions to preserve ordering.
        self.store.compare_and_set(k, v, min_version=ver)
        # Only clear if nobody overwrote during the flush.
        if self.dirty.get(k) == (v, ver):
            del self.dirty[k]

    def flush_oldest(self):
        k = next(iter(self.dirty))  # real code: oldest by seq, batched, concurrent
        self.flush(k)

    def evict(self, k):
        # Never drop a dirty entry without a successful flush.
        if k in self.dirty:
            self.flush(k)
        self.cache.pop(k, None)
